D.guides.shaman = {
 {
  id="sha-enhancement-wowvendor-waspers",
  spec="Enhancement",
  label="Enhancement · WowVendor · Waspers lv 10-30 0/21/0",
  kind="exact-order",
  default=true,
  note="Exact point order from the guide. Source notes: All rows and prerequisites check out against the verified tree: Mental Dexterity at 5, Shamanistic Focus at 10, Stormstrike at 15, Flurry after Mental Dexterity 3/3, Improved Stormstrike at 20 with Stormstrike taken. The article is dated Oct 4 (modified Oct 12), before the Oct 15 dev notes, but those notes did not touch the Enhancement layout this build uses.",
  priorities="Level-by-level table: L10-14 Thundering Strikes 5, L15-17 Mental Dexterity 3, L18-19 Improved Ghost Wolf 2, L20 Shamanistic Focus, L21-23 Elemental Weapons 3, L24 Ancestral Knowledge 1, L25 Stormstrike, L26-29 Flurry 4, L30 Improved Stormstrike 1. Stormstrike is the centrepiece. Improved Stormstrike's first point gives a chance for 50% in-combat mana regen and dodge/parry Stormstrike resets. Elemental Weapons matters at 30 because Windfury Weapon unlocks then. The site calls Enhancement the best Shaman leveling spec (lowest downtime). Preliminary level-60 targets: 16/35/0, also 17/34/0 (PvE) and 12/39/0 (PvP), toward Maelstrom Weapon, Mental Quickness, Improved Stormstrike 2/2 and Rage of the Farseer. Only the splits are given, no allocation.",
  source={
   site="WowVendor",
   author="Waspers",
   title="Best WoW Forever Shaman talents and leveling builds (Enhancement section)",
   url="https://wowvendor.com/media/wow-forever/forever-shaman-best-talents/",
   updated="2026-10-12",
   scope="10-30",
   purpose="leveling"
  },
  order={"thundering-strikes","thundering-strikes","thundering-strikes","thundering-strikes","thundering-strikes","mental-dexterity","mental-dexterity","mental-dexterity","improved-ghost-wolf","improved-ghost-wolf","shamanistic-focus","elemental-weapons","elemental-weapons","elemental-weapons","ancestral-knowledge","stormstrike","flurry","flurry","flurry","flurry","improved-stormstrike"}
 },
 {
  id="sha-enhancement-mobalytics-nicktew",
  spec="Enhancement",
  label="Enhancement · Mobalytics · NickTew lv 10-20 0/11/0",
  kind="exact-order",
  default=false,
  note="Exact point order from the guide. Source notes: Only the 1-20 variant could be read. The page also has a 20-30 variant tab that is not in the fetched text, so points 12-21 are unknown and none were filled in. Rows check out: Shamanistic Focus (row 3) is the 11th point, with 10 already spent.",
  priorities="'Point Order' list for the 1-20 variant: Thundering Strikes 5/5 (crit), Mental Dexterity 3/3 (Int to AP), Improved Ghost Wolf 2/2, Shamanistic Focus 1/1 (much cheaper shocks). The embedded tree shows exactly these 11 points (0/11/0). Optional tip: put 2 points in Improved Lightning Shield before level 20 (when Ghost Wolf is learned) and respec. Stat order: Strength > Intellect > Agility. Dungeons: Flame Shock, Searing Totem, then Fire Nova on cooldown.",
  source={
   site="Mobalytics",
   author="NickTew",
   title="Shaman Leveling Guide (Level 1-30) - Talents, Rotations, Races & More",
