   updated="2026-10-24",
   scope="10-20",
   purpose="leveling"
  },
  order={"thundering-strikes","thundering-strikes","thundering-strikes","thundering-strikes","thundering-strikes","mental-dexterity","mental-dexterity","mental-dexterity","improved-ghost-wolf","improved-ghost-wolf","shamanistic-focus"}
 },
 {
  id="sha-enhancement-wowhead-yebb",
  spec="Enhancement",
  label="Enhancement · Wowhead · Yebb lv 10-30",
  kind="priorities",
  default=false,
  note="Priorities only — no readable allocation. ◆ marks the talents the guide stresses. Source notes: No allocation can be read, so there is nothing to validate. All named talents are in the verified list.",
  priorities="The build is in a talent-calculator embed that does not show as text, so no ranks or order are given. The text says the build gives early damage, cheaper shocks (Shamanistic Focus), an instant Ghost Wolf usable indoors (Improved Ghost Wolf), stronger weapon imbues (Elemental Weapons) and mana return (Improved Stormstrike). Option: put points in Restoration instead for more Fire Nova and off-healing in dungeons. Legacy bonus points: finish Improved Stormstrike (100% chance), plus Spirit Weapons for parry-driven Stormstrike resets. Avoid Maelstrom Weapon until you can take 5/5. Dungeons: Searing Totem, then Fire Nova as much as threat and mana allow. The level-20 overview (same author, https://www.wowhead.com/forever/guide/classes/shaman/enhancement/level-20-dps-overview) uses the same text, and its build is also not readable.",
